  // DEALS
  'get_deals','get_deal','search_deals','get_deals_by_user','get_deals_by_stage',
  'change_assignee','change_stage','update_deal',

  // LEADS
  'get_leads','get_lead','search_leads','get_leads_by_user',

  // CONTACTS
  'get_contacts','get_contact','search_contacts',

  // COMPANIES
  'get_companies','get_company','search_companies',

  // CRM STRUCTURE
  'get_pipelines','get_pipeline_stages',

  // CRM ACTIVITIES / CALLS
  'get_activities','get_activity','search_activities','get_activity_audit_bindings',
  'get_activities_created_today','get_activities_today',
  'get_activities_by_user','get_activities_by_owner','get_activities_by_deal',
  'get_completed_activities_today','get_calls_today','get_calls_by_user',
  'get_open_activities_by_user','get_overdue_activities','get_activity_fields',
  'get_completion_audit','get_exact_completion_audit','setup_activity_audit','daily_crm_report','get_sales_team_daily_report','get_daily_call_report','get_user_daily_activity','ask_crm'
];

const requestedAction = String(body.action || '').trim();
if (!requestedAction) throw new Error('action zorunludur');
if (!allowedActions.includes(requestedAction)) throw new Error(`Geçersiz action: ${requestedAction}`);

// MCP için yeni, anlaşılır action adı.
// Mevcut çalışan günlük rapor zincirini bozmadan aynı route'a yönlendirir.
const actionAliases = {
  get_daily_call_report: 'get_sales_team_daily_report'
};
const action = actionAliases[requestedAction] || requestedAction;

let resource = null;
if (['get_users','get_user','search_users'].includes(action)) resource = 'users';
else if (['get_deals','get_deal','search_deals','get_deals_by_user','get_deals_by_stage','change_assignee','change_stage','update_deal'].includes(action)) resource = 'deals';
else if (['get_leads','get_lead','search_leads','get_leads_by_user'].includes(action)) resource = 'leads';
else if (['get_contacts','get_contact','search_contacts'].includes(action)) resource = 'contacts';
else if (['get_companies','get_company','search_companies'].includes(action)) resource = 'companies';
else if (['get_pipelines','get_pipeline_stages'].includes(action)) resource = 'crm_structure';
else if (action.startsWith('get_activit') || action.startsWith('search_activit') || action.startsWith('get_calls') || action.startsWith('get_completed_activit') || action.startsWith('get_open_activit') || action.startsWith('get_overdue_activit') || ['get_completion_audit','get_exact_completion_audit','setup_activity_audit','daily_crm_report','get_sales_team_daily_report','get_daily_call_report','get_user_daily_activity','ask_crm'].includes(action)) resource = 'activities';

const idRequiredActions = ['get_deal','get_lead','get_contact','get_company','get_user','get_activity','change_assignee','change_stage','update_deal'];
if (idRequiredActions.includes(action) && (body.id === undefined || body.id === null || String(body.id).trim() === '')) {
  throw new Error(`${action} için id zorunludur`);
}

if (action === 'change_assignee' && (body.assigned_by_id === undefined || body.assigned_by_id === null || String(body.assigned_by_id).trim() === '')) {
  throw new Error('change_assignee için assigned_by_id zorunludur');
}
if (action === 'change_stage' && !String(body.stage_id || '').trim()) {
  throw new Error('change_stage için stage_id zorunludur');
}
if (action === 'update_deal' && (!body.fields || typeof body.fields !== 'object' || Array.isArray(body.fields) || Object.keys(body.fields).length === 0)) {
  throw new Error('update_deal için fields zorunludur');
}

const searchActions = ['search_users','search_deals','search_leads','search_contacts','search_companies','search_activities'];
if (searchActions.includes(action) && !String(body.query || '').trim()) {
  throw new Error(`${action} için query zorunludur`);
}

if (['get_deals_by_user','get_leads_by_user'].includes(action) && (body.assigned_by_id === undefined || body.assigned_by_id === null || String(body.assigned_by_id).trim() === '')) {
  throw new Error(`${action} için assigned_by_id zorunludur`);
}
if (action === 'get_deals_by_stage' && !String(body.stage_id || '').trim()) {
  throw new Error('get_deals_by_stage için stage_id zorunludur');
}
