const p = Object.fromEntries(parts.map(x => [x.type, x.value]));
const today = `${p.year}-${p.month}-${p.day}`;
const today_from = `${today}T00:00:00+03:00`;
const today_to = `${today}T23:59:59+03:00`;

let date_from = body.date_from ? String(body.date_from) : null;
let date_to = body.date_to ? String(body.date_to) : null;
const question = String(body.question || body.soru || '').trim();
const user_name = String(body.user_name || body.personel || '').trim();

// ask_crm doğal dil tarih çözümleme (Europe/Istanbul)
if (action === 'ask_crm') {
  if (!question) throw new Error('ask_crm için question zorunludur');
  const q = question.toLocaleLowerCase('tr-TR');
  const day = new Date(`${today}T12:00:00+03:00`);
  const isoDay = (dt) => new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(dt);
  if (q.includes('dün') || q.includes('dunku') || q.includes('dünkü')) {
    const x=new Date(day); x.setDate(x.getDate()-1); const ds=isoDay(x); date_from=`${ds}T00:00:00+03:00`; date_to=`${ds}T23:59:59+03:00`;
  } else {
    const m=q.match(/son\s+(\d+)\s+g[uü]n/);
    if (m) { const n=Math.max(1,Math.min(Number(m[1]),30)); const x=new Date(day); x.setDate(x.getDate()-(n-1)); const ds=isoDay(x); date_from=`${ds}T00:00:00+03:00`; date_to=today_to; }
    else { date_from=date_from||today_from; date_to=date_to||today_to; }
  }
}

const writeActions = ['change_assignee','change_stage','update_deal'];
const is_write = writeActions.includes(action);

return [{
  json: {
    success: true,
    requested_action: requestedAction,
    action, resource,
    operation: is_write ? 'write' : 'read',
    is_write,
    id: body.id ?? null,
    deal_id: body.deal_id ?? null,
    category_id: body.category_id ?? null,
    stage_id: body.stage_id ?? null,
    status_id: body.status_id ?? null,
    assigned_by_id: body.assigned_by_id ?? null,
    responsible_id: responsibleId,
    owner_id: body.owner_id ?? null,
    owner_type_id: body.owner_type_id ?? null,
    activity_type_id: body.activity_type_id ?? null,
    completed: body.completed ?? null,
    query: String(body.query || '').trim(),
    filter, fields,
    limit, start,
    date_from, date_to,
    question, user_name,
    today_from, today_to,
    request: body
  }
}];

