const input = $input.first().json;

// ============================================================
// XRE BITRIX24 - ACTIVITY AUDIT EVENT NORMALIZER
// Events:
// ONCRMACTIVITYADD
// ONCRMACTIVITYUPDATE
// ONCRMACTIVITYDELETE
// ============================================================

// n8n Webhook node çıktısı
const body = input.body ?? input;
const query = input.query ?? {};
const headers = input.headers ?? {};

// ------------------------------------------------------------
// 1. EVENT
// ------------------------------------------------------------

const event = String(
  body.event ??
  body.EVENT ??
  ''
)
  .toUpperCase()
  .trim();

if (!event) {
  throw new Error('BITRIX_EVENT_MISSING');
}

// Sadece CRM Activity eventlerini kabul et
const allowedEvents = [
  'ONCRMACTIVITYADD',
  'ONCRMACTIVITYUPDATE',
  'ONCRMACTIVITYDELETE',
];

if (!allowedEvents.includes(event)) {
  throw new Error(`UNSUPPORTED_BITRIX_EVENT: ${event}`);
}

// ------------------------------------------------------------
// 2. ACTIVITY ID
// ------------------------------------------------------------

// Bitrix outgoing webhook bazı kurulumlarda:
// data[FIELDS][ID] = 123
//
// bazı yapılarda:
// data: {
//   FIELDS: {
//     ID: 123
//   }
// }
//
// şeklinde gelebilir.

const activityIdRaw =
  body['data[FIELDS][ID]'] ??
  body?.data?.FIELDS?.ID ??
  body?.data?.fields?.ID ??
  body?.data?.fields?.id ??
  body?.data?.ID ??
  body?.data?.id ??
  body?.FIELDS?.ID ??
  body?.FIELDS?.id ??
  null;

const activityId = String(activityIdRaw ?? '').trim();

if (!activityId) {
  throw new Error(
    `ACTIVITY_ID_MISSING | event=${event}`
  );
}

// ID sadece sayı olmalı
if (!/^\d+$/.test(activityId)) {
  throw new Error(
    `INVALID_ACTIVITY_ID: ${activityId}`
  );
}

// ------------------------------------------------------------
// 3. EVENT TYPE
// ------------------------------------------------------------

let eventType = 'unknown';

switch (event) {
  case 'ONCRMACTIVITYADD':
    eventType = 'created';
    break;

  case 'ONCRMACTIVITYUPDATE':
    eventType = 'updated';
    break;

  case 'ONCRMACTIVITYDELETE':
    eventType = 'deleted';
    break;
}

// ------------------------------------------------------------
// 4. BITRIX AUTH / PORTAL INFORMATION
// ------------------------------------------------------------

const domain =
  body['auth[domain]'] ??
  body?.auth?.domain ??
  null;

const memberId =
  body['auth[member_id]'] ??
  body?.auth?.member_id ??
  null;

const clientEndpoint =
  body['auth[client_endpoint]'] ??
  body?.auth?.client_endpoint ??
  null;

const serverEndpoint =
  body['auth[server_endpoint]'] ??
  body?.auth?.server_endpoint ??
  null;

const applicationToken =
  body['auth[application_token]'] ??
  body?.auth?.application_token ??
  null;

// ------------------------------------------------------------
// 5. EVENT HANDLER ID
// ------------------------------------------------------------

const eventHandlerId =
  body.event_handler_id ??
  body.EVENT_HANDLER_ID ??
  null;

// ------------------------------------------------------------
// 6. BITRIX TIMESTAMP
// ------------------------------------------------------------

const bitrixTimestampRaw =
  body.ts ??
  body.TS ??
  null;

let bitrixTimestamp = null;

if (bitrixTimestampRaw !== null) {
  const timestampNumber = Number(bitrixTimestampRaw);

  if (Number.isFinite(timestampNumber)) {
    // Bitrix ts saniye cinsindeyse milisaniyeye çevir
    const milliseconds =
      timestampNumber < 1000000000000
        ? timestampNumber * 1000
        : timestampNumber;

    const parsedDate = new Date(milliseconds);

    if (!Number.isNaN(parsedDate.getTime())) {
      bitrixTimestamp = parsedDate.toISOString();
    }
  }
}

// ------------------------------------------------------------
// 7. RECEIVED AT
// ------------------------------------------------------------

const receivedAt = new Date().toISOString();

// ------------------------------------------------------------
// 8. EVENT KEY
//
// Aynı Bitrix webhook'unu takip edebilmek için deterministik
// bir anahtar. Database tarafındaki unique/dedup işlemlerinde
// kullanılabilir.
// ------------------------------------------------------------

const eventKey = [
  event,
  activityId,
  String(bitrixTimestampRaw ?? ''),
  String(eventHandlerId ?? ''),
].join(':');

// ------------------------------------------------------------
// 9. DELETE EVENT KONTROLÜ
//
// DELETE durumunda crm.activity.get artık aktiviteyi
// bulamayabilir. Sonraki node bunu dikkate almalı.
// ------------------------------------------------------------

const isDeleted =
  event === 'ONCRMACTIVITYDELETE';

// ------------------------------------------------------------
// 10. OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      success: true,

      source: 'bitrix_outgoing_webhook',

      event: event,
      event_type: eventType,

      activity_id: activityId,

      is_deleted: isDeleted,

      event_handler_id:
        eventHandlerId !== null
          ? String(eventHandlerId)
          : null,

      bitrix_timestamp: bitrixTimestamp,

      received_at: receivedAt,

      event_key: eventKey,

      bitrix: {
        domain:
          domain !== null
            ? String(domain)
            : null,

        member_id:
          memberId !== null
            ? String(memberId)
            : null,

        client_endpoint:
          clientEndpoint !== null
            ? String(clientEndpoint)
            : null,

        server_endpoint:
          serverEndpoint !== null
            ? String(serverEndpoint)
            : null,

        application_token:
          applicationToken !== null
            ? String(applicationToken)
            : null,
      },

      request: {
        host:
          headers.host ??
          null,

        user_agent:
          headers['user-agent'] ??
          null,

        content_type:
          headers['content-type'] ??
          null,
      },

      // Debug/audit için orijinal Bitrix payload
      raw_event: body,
    },
  },
];

const response = $input.first().json;
const activity = response?.result ?? response;
const evt = $('Normalize Activity Audit Event').first().json;

const id = String(activity?.ID || evt.activity_id || '').trim();
if (!id) throw new Error('ACTIVITY_ID_MISSING');

const completedRaw = String(activity?.COMPLETED ?? '').toUpperCase().trim();
const completed = completedRaw === 'Y' ? 'Y' : completedRaw === 'N' ? 'N' : '';

const receivedAt = evt.received_at || new Date().toISOString();
const bitrixUpdatedAt =
  activity?.LAST_UPDATED ||
  activity?.LAST_UPDATED_DATE ||
  activity?.DATE_MODIFY ||
  null;

// Aynı Bitrix update'in tekrar gelmesi halinde duplicate kayıt oluşmasını önler.
const eventKey = [
  id,
  evt.event,
  bitrixUpdatedAt || receivedAt
].join(':');

return [{
  json: {
    success: true,
    event_key: eventKey,
    event: evt.event,
    event_type: evt.event_type,
    activity_id: id,
    received_at: receivedAt,
    bitrix_last_updated: bitrixUpdatedAt,
