    editor_id: String(activity?.EDITOR_ID ?? ''),
    owner_type_id: String(activity?.OWNER_TYPE_ID ?? ''),
    owner_id: String(activity?.OWNER_ID ?? ''),

    subject: activity?.SUBJECT ?? '',
    provider_id: activity?.PROVIDER_ID ?? '',
    provider_type_id: activity?.PROVIDER_TYPE_ID ?? '',
    direction: String(activity?.DIRECTION ?? ''),

    activity
  }
}];

const req = $('Validate Request').first().json;
const rows = $input.all().map(x => x.json);

return [{
  json: {
    success: true,
    action: 'get_exact_completion_audit',
    period: {
      from: req.date_from || req.today_from,
      to: req.date_to || req.today_to,
      time_zone: 'Europe/Istanbul'
    },
    count: rows.length,
    result: rows,
    note: 'PostgreSQL exact audit: yalnızca gözlenen COMPLETED N→Y geçişleri listelenir.'
  }
}];
